/bin/zsh -lc "PYTHONDONTWRITEBYTECODE=1 python3 -c \"import parser; cases=[1,0,-2,'3',1.2,None,True]; [print(repr(case)+' -> '+repr(parser.parse(case))+' ('+type(parser.parse(case)).__name__+')') if not isinstance(case,(type(None),)) else print(repr(case)+' -> '+repr(parser.parse(case))) for case in cases]\" 2>&1 || true
PYTHONDONTWRITEBYTECODE=1 python3 -c \"import parser; cases=[1,0,-2,'3',1.2,None,True];
for case in cases:
 try: print(repr(case)+' -> '+repr(parser.parse(case))+' ('+type(parser.parse(case)).__name__+')')
 except Exception as exc: print(repr(case)+' -> '+type(exc).__name__+': '+str(exc))\""

